      "evidence": [
        "baseline.controller_freq_hz",
        "baseline.pendulum_freq_hz",
        "baseline.controller_freq_ratio",
        "baseline.step_length_over_leg",
        "baseline.pitch_at_end_rad",
        "baseline.forward_fall_frac"
      ],
      "competing": [
        "Stride amplitudes (hip_amp, knee_amp) may be too small for the longer legs, not frequency."
      ]
    },
    {
      "id": "H2",
      "mechanism": "Torque authority (tau_ratio=0.398) is far below the reference (0.995), limiting push-off despite zero torque saturation (peak torques 0.49-0.62 of limit). Raising torque limit should increase achievable acceleration.",
      "evidence": [
        "creature.features.tau_ratio",
        "creature.reference.features.tau_ratio",
        "baseline.saturation_frac",
        "baseline.peak_tau_over_limit_hip",
        "baseline.peak_tau_over_limit_knee",
        "baseline.peak_tau_over_limit_ankle"
      ],
      "competing": [
        "Torque may not be limiting because saturation is zero; the controller may simply not demand enough torque due to feedback gains."
      ]
    },
    {
      "id": "H3",
      "mechanism": "Foot is very short relative to leg (foot_to_leg=0.064 vs reference 0.267), reducing ankle leverage and capture margin (mean -0.42 leg lengths). Lengthening the foot should improve push-off and foot placement relative to the capture point.",
